import { ExportNames } from "@/global";
import type { Project } from "@/types";
import { writeFileSync } from "node:fs";

type PlayFiles = { ps1: string; sh: string };


export function makePlayFiles(project: Project): PlayFiles {
  const f = {
    ps1: "\n\n",
    sh: "#!/usr/bin/env bash\n\n",
  };

  const versionString = __VERSION__ ? `Version: ${__VERSION__}\n` : "";
  const repoString = __REPOSITORY_URL__ ? `Repository: ${__REPOSITORY_URL__}\n` : "";
  const contactString = __AUTHOR__?.email ? `Contact: ${__AUTHOR__.email}\n` : "";

  comment(f, `
    This file was generated by Stockholm Trekkers Playlist Maker${__AUTHOR__?.name ? `, made by ${__AUTHOR__.name}` : ""}.
    ${versionString}${repoString}${contactString}
    Options revision: ${project.optionsRev}
  `);

  ensureVLC(f);

  for (const block of project.blocks) {
    const blockEpisodes = project.episodes.filter(e => e.blockID === block.id);
    comment(f, `
      Block starting at ${block.startTime ?? "unknown time"} with ${blockEpisodes.length} ${blockEpisodes.length === 1 ? "episode" : "episodes"}
    `);
  }

  return f;
}

