function hashComment(text: string): string {
  return text.split("\n").map(line => `# ${line}`).join("\n");
}
function comment(files: PlayFiles, text: string): void {
  const t = text.trim().split("\n").map(line => line.trimStart()).join("\n");
  files.ps1 += hashComment(t) + "\n\n";
  files.sh += hashComment(t) + "\n\n";
}

function ensureVLC(files: PlayFiles): void {
  // Start VLC and wait for it to be ready before the playlist starts playing
  const vlcCommand = "vlc --intf dummy --play-and-exit";
  files.ps1 += `Start-Process -FilePath "vlc" -ArgumentList "--intf dummy --play-and-exit" -WindowStyle Hidden\n\n`;
  files.sh += `${vlcCommand} &\n\n`;
}

